import{f as e,g as t,l as n,n as r,p as i,s as a}from"./index-Bw06dwPt.js";import{t as o}from"./navigate-CjdYr8GP.js";var s={name:`FrontendHtmlCssPage`,methods:{handleNav(e){o(e)}}},c={class:`htmlcss-page`,style:{"--color-accent":`#7c5cfc`}},l={class:`page`},u={class:`topbar`},d={class:`links`};function f(r,o,s,f,p,m){return t(),e(`div`,c,[n(`div`,l,[n(`div`,u,[o[2]||=n(`h1`,null,`🎨 HTML & CSS`,-1),n(`div`,d,[n(`a`,{href:`#`,onClick:o[0]||=a(e=>m.handleNav(`/frontend/hub`),[`prevent`])},`← Frontend`),n(`a`,{href:`#`,onClick:o[1]||=a(e=>m.handleNav(`/`),[`prevent`])},`Trang chủ`)])]),o[3]||=i(`<p class="desc" data-v-566bb295>Từ semantic HTML đến CSS hiện đại: Flexbox, Grid, Animation, Custom Properties, BEM, và 25+ kỹ thuật thực tế.</p><div class="section" data-v-566bb295><h2 data-v-566bb295>📐 HTML5 Semantic</h2><p data-v-566bb295>Các thẻ semantic giúp SEO, accessibility, và maintain code tốt hơn.</p><pre data-v-566bb295><code data-v-566bb295>&lt;header&gt; &lt;nav&gt; &lt;main&gt; &lt;section&gt; &lt;article&gt; &lt;aside&gt; &lt;footer&gt;</code></pre><div class="grid-2" data-v-566bb295><div class="card" data-v-566bb295><h4 data-v-566bb295>&lt;header&gt;</h4><p data-v-566bb295>Đầu trang, chứa logo, navigation, search bar</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>&lt;nav&gt;</h4><p data-v-566bb295>Điều hướng chính, menu links</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>&lt;main&gt;</h4><p data-v-566bb295>Nội dung chính, chỉ 1 lần/trang</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>&lt;article&gt;</h4><p data-v-566bb295>Nội dung độc lập, có thể tái sử dụng</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>&lt;section&gt;</h4><p data-v-566bb295>Nhóm nội dung theo chủ đề</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>&lt;aside&gt;</h4><p data-v-566bb295>Nội dung liên quan, sidebar</p></div></div></div><div class="section" data-v-566bb295><h2 data-v-566bb295>📦 CSS Box Model &amp; Units</h2><pre data-v-566bb295><code data-v-566bb295>* { box-sizing: border-box; } /* content-box vs border-box */</code></pre><p data-v-566bb295><strong data-v-566bb295>Units:</strong> <code data-v-566bb295>px</code> (cố định), <code data-v-566bb295>rem</code> (dựa trên root font-size), <code data-v-566bb295>em</code> (dựa trên parent), <code data-v-566bb295>%</code>, <code data-v-566bb295>vw/vh</code> (viewport), <code data-v-566bb295>ch</code> (độ rộng chữ), <code data-v-566bb295>fr</code> (fraction trong grid)</p></div><div class="section" data-v-566bb295><h2 data-v-566bb295>🧩 Flexbox</h2><p data-v-566bb295>Bố cục 1 chiều — dùng cho navigation, card rows, center content.</p><pre data-v-566bb295><code data-v-566bb295>.container {
  display: flex;
  justify-content: center; /* flex-start | center | space-between | space-around */
  align-items: center;     /* stretch | center | flex-start */
  gap: 1rem;               /* khoảng cách giữa các item */
  flex-wrap: wrap;         /* xuống dòng khi hết chỗ */
}
.item { flex: 1; }          /* chia đều không gian */</code></pre></div><div class="section" data-v-566bb295><h2 data-v-566bb295>🔲 CSS Grid</h2><p data-v-566bb295>Bố cục 2 chiều — dùng cho layout chính, gallery, dashboard.</p><pre data-v-566bb295><code data-v-566bb295>.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);  /* 3 cột bằng nhau */
  grid-template-columns: 200px 1fr;        /* sidebar + content */
  gap: 1rem;
}
.item { grid-column: span 2; }            /* chiếm 2 cột */
.item { grid-area: 1 / 1 / 3 / 3; }       /* row-start / col-start / row-end / col-end */</code></pre></div><div class="section" data-v-566bb295><h2 data-v-566bb295>🎭 CSS Custom Properties (Variables)</h2><pre data-v-566bb295><code data-v-566bb295>:root {
  --primary: #6366f1;
  --radius: 8px;
  --shadow: 0 2px 8px rgba(0,0,0,0.1);
}
.btn { background: var(--primary); border-radius: var(--radius); }
/* Fallback: var(--primary, blue) */</code></pre></div><div class="section" data-v-566bb295><h2 data-v-566bb295>✨ CSS Animations &amp; Transitions</h2><pre data-v-566bb295><code data-v-566bb295>.btn {
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.3s;
}
.btn:hover { transform: translateY(-3px) scale(1.02); box-shadow: 0 8px 24px rgba(0,0,0,0.15); }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}
.box { animation: fadeIn 0.5s ease forwards; }</code></pre></div><div class="section" data-v-566bb295><h2 data-v-566bb295>🧱 BEM Methodology</h2><pre data-v-566bb295><code data-v-566bb295>/* Block__Element--Modifier */
.card { }                    /* Block */
.card__title { }             /* Element */
.card__title--highlight { }  /* Modifier */
.card--featured { }          /* Modifier của Block */</code></pre></div><div class="section" data-v-566bb295><h2 data-v-566bb295>🎪 25+ CSS Techniques</h2><div class="grid-2" data-v-566bb295><div class="card" data-v-566bb295><h4 data-v-566bb295>Hover Effect</h4><p data-v-566bb295><code data-v-566bb295>cubic-bezier</code> spring + glow shadow</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Tooltip</h4><p data-v-566bb295><code data-v-566bb295>[data-tooltip]::after</code> CSS-only</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Glassmorphism</h4><p data-v-566bb295><code data-v-566bb295>backdrop-filter: blur(14px)</code></p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Neumorphism</h4><p data-v-566bb295>Inset/outset soft shadows</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Card Hover</h4><p data-v-566bb295>Sweep shimmer <code data-v-566bb295>::before</code></p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Ripple Effect</h4><p data-v-566bb295>JS + <code data-v-566bb295>@keyframes</code></p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Skeleton</h4><p data-v-566bb295>Shimmer gradient animation</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Gradient Text</h4><p data-v-566bb295><code data-v-566bb295>background-clip: text</code></p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Flip Card</h4><p data-v-566bb295><code data-v-566bb295>perspective + rotateY</code></p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Accordion</h4><p data-v-566bb295>Checkbox hack CSS-only</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Modal</h4><p data-v-566bb295><code data-v-566bb295>:target</code> pseudo-class</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Toggle Switch</h4><p data-v-566bb295>Checkbox styling + spring</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Custom Scrollbar</h4><p data-v-566bb295><code data-v-566bb295>::-webkit-scrollbar</code></p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Masonry</h4><p data-v-566bb295><code data-v-566bb295>columns: 3</code></p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Parallax</h4><p data-v-566bb295><code data-v-566bb295>background-attachment</code></p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Loading Spinner</h4><p data-v-566bb295>Border rotation keyframe</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Timeline</h4><p data-v-566bb295><code data-v-566bb295>::before</code> line + dots</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Animated Button</h4><p data-v-566bb295>Slide fill <code data-v-566bb295>::before</code></p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Sticky Header</h4><p data-v-566bb295><code data-v-566bb295>position: sticky</code></p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Dropdown</h4><p data-v-566bb295>CSS hover menu</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Sidebar</h4><p data-v-566bb295>Checkbox toggle animation</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Responsive Nav</h4><p data-v-566bb295>Media query + hamburger</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Image Zoom</h4><p data-v-566bb295><code data-v-566bb295>scale(1.25)</code> overflow hidden</p></div><div class="card" data-v-566bb295><h4 data-v-566bb295>Carousel</h4><p data-v-566bb295>JS + CSS <code data-v-566bb295>translateX</code></p></div></div></div>`,9)])])}var p=r(s,[[`render`,f],[`__scopeId`,`data-v-566bb295`]]);export{p as default};